CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL,
 full_name text NOT NULL, phone text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','pending')),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS roles (id smallserial PRIMARY KEY, name text NOT NULL UNIQUE);
INSERT INTO roles(name) VALUES ('guest'),('owner'),('manager'),('staff'),('admin') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id smallint NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id, role_id));
CREATE TABLE IF NOT EXISTS user_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS owner_profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, legal_name text, verification_status text NOT NULL DEFAULT 'pending', payout_reference text);
CREATE TABLE IF NOT EXISTS guest_profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS properties (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid REFERENCES users(id), slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL DEFAULT '', city text NOT NULL, region text NOT NULL, country text NOT NULL DEFAULT 'India', accommodation_type text NOT NULL, max_guests integer NOT NULL CHECK(max_guests > 0), bedrooms integer NOT NULL CHECK(bedrooms >= 0), bathrooms numeric(4,1) NOT NULL CHECK(bathrooms >= 0), base_nightly_price numeric(12,2) NOT NULL CHECK(base_nightly_price >= 0), currency char(3) NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','under_review','approved','published','rejected','suspended')), management_model text NOT NULL DEFAULT 'marketplace' CHECK(management_model IN ('marketplace','managed')), average_rating numeric(3,2), is_featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS tagline text DEFAULT '';
ALTER TABLE properties ADD COLUMN IF NOT EXISTS category text DEFAULT 'Private Pool Villas';
ALTER TABLE properties ADD COLUMN IF NOT EXISTS cleaning_fee numeric(12,2) DEFAULT 3500;
CREATE INDEX IF NOT EXISTS properties_search_idx ON properties(status, city, base_nightly_price);
CREATE TABLE IF NOT EXISTS property_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, url text NOT NULL, storage_key text, alt_text text NOT NULL DEFAULT '', is_cover boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS amenities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS property_amenities (property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, amenity_id uuid NOT NULL REFERENCES amenities(id) ON DELETE CASCADE, PRIMARY KEY(property_id, amenity_id));
CREATE TABLE IF NOT EXISTS property_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, storage_key text NOT NULL, document_type text NOT NULL, review_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_managers (property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(property_id,user_id));
CREATE TABLE IF NOT EXISTS availability_calendar (property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, stay_date date NOT NULL, is_available boolean NOT NULL DEFAULT true, nightly_price numeric(12,2), minimum_stay integer NOT NULL DEFAULT 1, PRIMARY KEY(property_id,stay_date));
CREATE TABLE IF NOT EXISTS pricing_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, name text NOT NULL, rule_type text NOT NULL, amount numeric(12,2) NOT NULL, starts_on date, ends_on date, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, property_id uuid NOT NULL REFERENCES properties(id), guest_id uuid NOT NULL REFERENCES users(id), check_in date NOT NULL, check_out date NOT NULL, guests integer NOT NULL CHECK(guests > 0), status text NOT NULL DEFAULT 'pending_payment' CHECK(status IN ('pending_payment','confirmed','cancelled','completed','refunded')), currency char(3) NOT NULL, gross_total numeric(12,2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(check_out > check_in));
CREATE INDEX IF NOT EXISTS bookings_property_dates_idx ON bookings(property_id,check_in,check_out);
CREATE TABLE IF NOT EXISTS booking_guests (booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, full_name text NOT NULL, email text NOT NULL, PRIMARY KEY(booking_id,email));
CREATE TABLE IF NOT EXISTS booking_price_breakdowns (booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE, accommodation numeric(12,2) NOT NULL, cleaning numeric(12,2) NOT NULL DEFAULT 0, guest_fee numeric(12,2) NOT NULL DEFAULT 0, taxes numeric(12,2) NOT NULL DEFAULT 0, discounts numeric(12,2) NOT NULL DEFAULT 0, currency char(3) NOT NULL);
CREATE TABLE IF NOT EXISTS commissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid REFERENCES properties(id), owner_id uuid REFERENCES users(id), rate numeric(7,5) NOT NULL CHECK(rate BETWEEN 0 AND 1), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz);
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), provider text NOT NULL, provider_reference text, idempotency_key text NOT NULL UNIQUE, amount numeric(12,2) NOT NULL, currency char(3) NOT NULL, status text NOT NULL DEFAULT 'initiated', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), amount numeric(12,2) NOT NULL, status text NOT NULL DEFAULT 'requested', reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS owner_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), booking_id uuid REFERENCES bookings(id), amount numeric(12,2) NOT NULL, currency char(3) NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES bookings(id), property_id uuid NOT NULL REFERENCES properties(id), guest_id uuid NOT NULL REFERENCES users(id), rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wishlists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wishlist_properties (wishlist_id uuid NOT NULL REFERENCES wishlists(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(wishlist_id,property_id));
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid REFERENCES bookings(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), requester_id uuid NOT NULL REFERENCES users(id), service_type text NOT NULL, status text NOT NULL DEFAULT 'requested', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cleaning_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), booking_id uuid REFERENCES bookings(id), assigned_to uuid REFERENCES users(id), due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'open', checklist jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS maintenance_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), reported_by uuid REFERENCES users(id), assigned_to uuid REFERENCES users(id), description text NOT NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), channel text NOT NULL, template_key text NOT NULL, status text NOT NULL DEFAULT 'queued', payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, discount_type text NOT NULL, amount numeric(12,2) NOT NULL, starts_at timestamptz, ends_at timestamptz, usage_limit integer, active boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), booking_id uuid REFERENCES bookings(id), subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
